#!/usr/bin/env bash
# Compose the always-loaded contract from base/ + overlay/ into per-harness files.
# Generated files are never edited by hand.
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[[ -f "$ROOT_DIR/overlay/config.sh" ]] && source "$ROOT_DIR/overlay/config.sh"
CENTRAL_DIR="${CENTRAL_DIR:-$ROOT_DIR}"

MODE="${1:-personal}"

compose() {
  local out="$1" overlay="${2:-yes}" subst="${3:-yes}"
  {
    if [[ "$overlay" == "yes" ]]; then
      echo "<!-- GENERATED by scripts/build.sh from base/ + overlay/. Do not edit. -->"
    else
      echo "<!-- GENERATED by scripts/build.sh from base/. __CENTRAL_DIR__ is"
      echo "     replaced with the real path when the adopter runs build.sh. -->"
    fi
    echo
    if [[ "$subst" == "yes" ]]; then
      sed "s|__CENTRAL_DIR__|${CENTRAL_DIR}|g" "$ROOT_DIR/base/contract.md"
    else
      cat "$ROOT_DIR/base/contract.md"
    fi
    if [[ "$overlay" == "yes" && -f "$ROOT_DIR/overlay/personal.md" ]]; then
      echo
      cat "$ROOT_DIR/overlay/personal.md"
    fi
  } > "$out"
}

case "$MODE" in
  personal)
    DIST="$ROOT_DIR/dist"
    rm -rf "$DIST"
    mkdir -p "$DIST"/{opencode,claude,codex,gemini,cursor/rules}

    compose "$DIST/agents.md" yes
    cp "$DIST/agents.md" "$ROOT_DIR/AGENTS.md"
    cp "$DIST/agents.md" "$DIST/opencode/AGENTS.md"
    cp "$DIST/agents.md" "$DIST/claude/CLAUDE.md"
    cp "$DIST/agents.md" "$DIST/codex/AGENTS.md"
    cp "$DIST/agents.md" "$DIST/gemini/GEMINI.md"

    {
      echo "---"
      echo "description: Global agent contract and policy router"
      echo "globs:"
      echo "alwaysApply: true"
      echo "---"
      echo
      cat "$DIST/agents.md"
    } > "$DIST/cursor/rules/agent-policy.mdc"

    echo "built: $DIST (personal)"
    ;;
  public)
    DIST="$ROOT_DIR/dist/public"
    rm -rf "$DIST"
    mkdir -p "$DIST"
    compose "$DIST/AGENTS.md" no no
    echo "built: $DIST/AGENTS.md (public, template placeholder kept)"
    ;;
  *)
    echo "usage: build.sh [personal|public]" >&2
    exit 2
    ;;
esac
